package com.therighthon.rnr.common.recipe;
import com.therighthon.rnr.RoadsAndRoofs; import net.minecraft.core.registries.Registries; import net.minecraft.world.item.crafting.RecipeType; import net.minecraftforge.registries.DeferredRegister; import net.minecraftforge.registries.RegistryObject;
public final class RNRRecipeTypes { public static final DeferredRegister<RecipeType<?>> RECIPE_TYPES=DeferredRegister.create(Registries.RECIPE_TYPE,RoadsAndRoofs.MOD_ID); private static <T extends net.minecraft.world.item.crafting.Recipe<?>> RegistryObject<RecipeType<T>> register(String n){return RECIPE_TYPES.register(n,()->new RecipeType<T>(){public String toString(){return RoadsAndRoofs.MOD_ID+":"+n;}});} public static final RegistryObject<RecipeType<RNRDamageInputsShapelessRecipe>> DAMAGE_INPUTS_SHAPELESS = register("damage_inputs_shapeless_crafting");
    public static final RegistryObject<RecipeType<MattockRecipe>> MATTOCK_RECIPE=register("mattock"); public static final RegistryObject<RecipeType<BlockModRecipe>> BLOCK_MOD_RECIPE=register("block_mod"); private RNRRecipeTypes(){} }
